import React from "react";
import { useNavigate } from "react-router-dom";
import {
  FaJava,
  FaPython,
  FaDatabase,
  FaChartLine,
  FaLaptopCode,
  FaReact
} from "react-icons/fa";

const Hero = () => {
  const navigate = useNavigate();

  return (
    <section className="hero">
      <div className="container">

        {/* LEFT SIDE (REDESIGNED) */}
        <div className="left">

          <div className="glassCard">

            <p className="tag">WELCOME TO MY PORTFOLIO</p>

            <h1>
              I'm <span className="name">Swetha A</span>
            </h1>

            <div className="chips">
              <span>Full Stack Developer</span>
              <span>System Designer</span>
              <span>UI Thinker</span>
            </div>

            <h2 className="role">
              Building scalable systems with clean design & strong logic
            </h2>

            <p className="desc">
              I specialize in transforming ideas into real-world applications
              using modern technologies like Java, React, Python, and databases.
              My focus is on performance, structure, and user experience.
            </p>

            <div className="buttons">
              <button className="btn primary" onClick={() => navigate("/projects")}>
                Explore Projects →
              </button>
              <button className="btn secondary" onClick={() => navigate("/about")}>
                About Me →
              </button>
            </div>

            {/* SKILL STRIP */}
            <div className="skills">
              <span>Java</span>
              <span>React</span>
              <span>Python</span>
              <span>MySQL</span>
              <span>UI/UX</span>
            </div>

          </div>

        </div>

        {/* RIGHT SIDE (UNCHANGED) */}
        <div className="right">
          <div className="radar">

            <div className="glow"></div>

            <div className="ring r1"></div>
            <div className="ring r2"></div>
            <div className="ring r3"></div>

            <div className="sweep"></div>

            <div className="center">
              <img
                src="https://cdn-icons-png.flaticon.com/512/3893/3893079.png"
                alt="girl working on laptop"
              />
            </div>

            <div className="orbit o1"><FaJava /></div>
            <div className="orbit o2"><FaPython /></div>
            <div className="orbit o3"><FaDatabase /></div>
            <div className="orbit o4"><FaChartLine /></div>
            <div className="orbit o5"><FaLaptopCode /></div>
            <div className="orbit o6"><FaReact /></div>

            <span className="particle p1"></span>
            <span className="particle p2"></span>
            <span className="particle p3"></span>
            <span className="particle p4"></span>
            <span className="particle p5"></span>
            <span className="particle p6"></span>

          </div>
        </div>

      </div>

      <style>{`

        .hero {
          min-height: 100vh;
          display: flex;
          align-items: center;
          background: radial-gradient(circle at top, #0b1220, #050816);
          padding: 0 6%;
        }

        .container {
          display: grid;
          grid-template-columns: 1.3fr 1fr;
          gap: 40px;
          width: 100%;
          align-items: center;
        }

        /* ================= LEFT SIDE NEW DESIGN ================= */

        .glassCard {
          background: rgba(255,255,255,0.04);
          backdrop-filter: blur(12px);
          border: 1px solid rgba(255,255,255,0.08);
          border-radius: 18px;
          padding: 35px;
          box-shadow: 0 0 40px rgba(56,189,248,0.08);
        }

        .tag {
          font-size: 12px;
          letter-spacing: 3px;
          color: #64748b;
        }

        h1 {
          font-size: 58px;
          margin: 10px 0;
        }

        .name {
          color: #38BDF8;
        }

        .chips {
          display: flex;
          gap: 10px;
          flex-wrap: wrap;
          margin: 10px 0 20px;
        }

        .chips span {
          font-size: 12px;
          padding: 6px 10px;
          border-radius: 20px;
          background: rgba(56,189,248,0.1);
          border: 1px solid rgba(56,189,248,0.2);
          color: #38BDF8;
        }

        .role {
          font-size: 18px;
          color: #94a3b8;
        }

        .desc {
          margin-top: 15px;
          color: #cbd5e1;
          line-height: 1.7;
        }

        .buttons {
          margin-top: 25px;
          display: flex;
          gap: 15px;
        }

        .btn {
          padding: 12px 22px;
          border-radius: 10px;
          border: 1px solid rgba(56,189,248,0.3);
          cursor: pointer;
        }

        .primary {
          background: #38BDF8;
          color: #0b1220;
        }

        .secondary {
          background: rgba(255,255,255,0.03);
          color: #38BDF8;
        }

        .skills {
          margin-top: 25px;
          display: flex;
          gap: 10px;
          flex-wrap: wrap;
        }

        .skills span {
          font-size: 11px;
          padding: 5px 10px;
          border-radius: 8px;
          background: rgba(255,255,255,0.05);
          color: #94a3b8;
        }

      `}</style>

    </section>
  );
};

export default Hero;
